/// Ports `clip_projector_type_from_string` (clip-impl.h:574 @5266f24da): the
/// first type, in enum order, whose name is `s`.
pub fn projectorTypeFromString(s: []const u8) ProjectorType {
    for (projector_type_names, 0..) |n, i| {
        if (n) |name| {
            if (std.mem.eql(u8, name, s)) return @fromBackingInt(@intCast(i));
        }
    }
    return .unknown;
}

/// The name `PROJECTOR_TYPE_NAMES[t]` gives, or null.
pub fn projectorTypeName(t: ProjectorType) ?[:0]const u8 {
    const i: usize = @intCast(@backingInt(t));
    return if (i < projector_type_names.len) projector_type_names[i] else null;
}

